from app import create_app
from app.models import Producto

app = create_app()
with app.app_context():
    from app.extensions import db

    # Restaurar imágenes originales
    imagenes_originales = {
        'Hamburguesa Clásicas': 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=400',
        'Hamburguesa la salvaje': 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR7eXFWmz-Yda00799aIPUhvyi5mIhjJLBsoA&s',
        'Hamburguesa Vegetariana': 'data:image/jpeg;base64,',
        'Hamburguesa Deluxe': 'https://images.unsplash.com/photo-1551782450-a2132b4ba21d?w=400',
        'Hamburguesa Picante': 'https://adamsfarms.com/wp-content/uploads/2021/05/Pepper-Jack-Jalapeno-Burgers.jpg'
    }

    for nombre, imagen in imagenes_originales.items():
        producto = Producto.query.filter_by(nombre=nombre).first()
        if producto:
            producto.img = imagen

    db.session.commit()
    print("Imágenes de hamburguesas restauradas a las originales.")

    # Mostrar productos actualizados
    productos_actualizados = Producto.query.all()
    print("\nProductos con imágenes originales:")
    for p in productos_actualizados:
        print(f"- {p.nombre}: {p.img[:50]}...")